using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Great.Parts.Cel.Eng.Checks;

/// <summary>A comment before the first token of a file.</summary>
/// <param name="Position">The place of the first character of the comment.</param>
/// <param name="Text">The text of the comment with its comment marks.</param>
internal sealed record LeadingComment(Position Position, string Text);

/// <summary>A C# file that Roslyn treats as generated by the signs in the file itself: the marker comment or the name.</summary>
/// <param name="Path">The path relative to the root, with <c>/</c>.</param>
/// <param name="Allowed">Whether the file is in a directory where generation is part of the design, see <see cref="GeneratedCode.AllowedDirectories"/>.</param>
/// <param name="HasMarker">Whether a comment before the first token has the marker.</param>
/// <param name="HasGeneratedName">Whether the file name is a sign of generated code.</param>
/// <param name="Position">The place of the comment with the marker, or <c>(1,1)</c> when only the name is a sign.</param>
/// <param name="Comments">The comments before the first token, in order; the reason of a suppression is read from them.</param>
internal sealed record GeneratedFile(
    string Path,
    bool Allowed,
    bool HasMarker,
    bool HasGeneratedName,
    Position Position,
    IReadOnlyList<LeadingComment> Comments);

/// <summary>The signs of generated code, as Roslyn reads them in the file itself, and the directories where generation is allowed.</summary>
internal static class GeneratedCode
{
    /// <summary>
    /// The directories where generated files are part of the design: they are outside every check. Adding one is a change of
    /// <c>docs/design/eng-checks-source.md</c> and of this list in one change set.
    /// </summary>
    internal static readonly IReadOnlyList<string> AllowedDirectories = ["src/Great.Parts.Cel/Library/Unicode/"];

    private static readonly string[] Markers = ["<auto-generated", "<autogenerated"];
    private static readonly string[] NameEndings = [".designer", ".generated", ".g", ".g.i"];
    private const string TemporaryName = "TemporaryGeneratedFile_";

    /// <summary>Returns whether the path is in an allowed directory.</summary>
    /// <param name="path">The path relative to the root, with <c>/</c>.</param>
    internal static bool IsInAllowedDirectory(string path) =>
        AllowedDirectories.Any(directory => path.StartsWith(directory, StringComparison.Ordinal));

    /// <summary>
    /// Returns whether the file name is a sign: it starts with <c>TemporaryGeneratedFile_</c>, or the name without the extension
    /// ends with <c>.designer</c>, <c>.generated</c>, <c>.g</c> or <c>.g.i</c>, ignoring case.
    /// </summary>
    /// <param name="path">The path of the file; only the name is read.</param>
    internal static bool HasGeneratedName(string path)
    {
        string name = Path.GetFileName(path);
        string withoutExtension = Path.GetFileNameWithoutExtension(name);
        return name.StartsWith(TemporaryName, StringComparison.OrdinalIgnoreCase)
            || NameEndings.Any(ending => withoutExtension.EndsWith(ending, StringComparison.OrdinalIgnoreCase));
    }

    /// <summary>Checks the signs of one file.</summary>
    /// <param name="path">The path relative to the root, with <c>/</c>.</param>
    /// <param name="tree">The syntax tree of the file.</param>
    /// <param name="lines">The lines of the text of the tree.</param>
    /// <returns>The file when it has a sign; <see langword="null"/> when it does not.</returns>
    internal static GeneratedFile? Inspect(string path, SyntaxTree tree, SourceLines lines)
    {
        List<LeadingComment> comments = [];
        Position? marker = null;
        foreach (SyntaxTrivia trivia in tree.GetRoot().GetFirstToken(includeZeroWidth: true).LeadingTrivia.Where(IsComment))
        {
            string text = trivia.ToString();
            Position position = lines.Locate(trivia.SpanStart);
            comments.Add(new LeadingComment(position, text));
            if (marker is null && Markers.Any(sign => text.Contains(sign, StringComparison.Ordinal)))
            {
                marker = position;
            }
        }

        bool named = HasGeneratedName(path);
        if (marker is null && !named)
        {
            return null;
        }

        return new GeneratedFile(path, IsInAllowedDirectory(path), marker is not null, named, marker ?? new Position(1, 1), comments);
    }

    /// <summary>
    /// Returns the attributes named <c>GeneratedCode</c> or <c>GeneratedCodeAttribute</c> with any qualifier, found in the tree
    /// without a compilation, the way a <c>SuppressMessage</c> attribute is found.
    /// </summary>
    /// <param name="root">The root of the tree.</param>
    internal static IEnumerable<AttributeSyntax> FindAttributes(SyntaxNode root) => SyntaxQueries.Attributes(root, "GeneratedCode");

    private static bool IsComment(SyntaxTrivia trivia) => trivia.Kind()
        is SyntaxKind.SingleLineCommentTrivia
        or SyntaxKind.MultiLineCommentTrivia
        or SyntaxKind.SingleLineDocumentationCommentTrivia
        or SyntaxKind.MultiLineDocumentationCommentTrivia;
}
